(function(){if(typeof document==='undefined')return;function showFoundation(){const s=window.NLDG_BOOK_STUDY,view=document.getElementById('book-view');if(!s||!view||s.lessons.some(x=>x.number===Number(new URLSearchParams(location.search).get('lesson')))||document.getElementById('ecclesiastes-foundation'))return;const section=document.createElement('section');section.id='ecclesiastes-foundation';section.className='series-guide';function panel(title,text,items){const a=document.createElement('article');a.className='lesson-panel';const h=document.createElement('h2');h.textContent=title;a.append(h);for(const t of String(text||'').split('\n\n').filter(Boolean)){const p=document.createElement('p');p.textContent=t;a.append(p);}if(items){const ol=document.createElement('ol');for(const t of items){const li=document.createElement('li');li.textContent=t;ol.append(li);}a.append(ol);}section.append(a);}panel('Pasaje principal de la serie',s.seriesMainScripture);panel('Pregunta central',s.seriesQuestion);panel('Apertura',s.seriesOpening);panel('Contexto bíblico',s.seriesContext);for(const t of s.seriesTeaching||[])panel(t.heading,t.body);panel('Conexión con Jesús',s.seriesJesusConnection);panel('No pases por alto esto',s.seriesGuardrail);panel('Preguntas para conversar','',s.seriesQuestions);panel('Examen personal',s.seriesExamination);panel('Práctica semanal',s.seriesPractice);panel('Orientación para líderes',s.seriesLeaderGuidance);panel('Conclusión',s.seriesClosingTakeaway);const prayer=view.querySelector('.series-prayer');view.insertBefore(section,prayer||null);window.NLDG_SCRIPTURE_LINKS?.linkReferences(section);}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',showFoundation,{once:true});else showFoundation();})();
